  n = Math.imul(n ^ (n >>> 15), 0x846ca68b);
  return (n ^ (n >>> 16)) >>> 0;
}
function hash01(a, b, c) {
  return hashU(hashU((a | 0) + 0x9E3779B9) ^ Math.imul((b | 0) + 0x85EBCA6B, 0x27D4EB2F) ^ Math.imul((c | 0) + 0x165667B1, 0x9E3779B1)) / 4294967296;
}
/* smooth seeded value noise of one variable, range [-1,1] */
function vnoise(x, seed) {
  const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f);
  const a = hash01(i, seed, 7) * 2 - 1, b = hash01(i + 1, seed, 7) * 2 - 1;
