function sstep(a, b, x) { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }
function smooth01(t) { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); }
function pulse(a, b, c, d, x) { return sstep(a, b, x) * (1 - sstep(c, d, x)); }
function smax(a, b, k) { const h = clamp(0.5 + 0.5 * (a - b) / k, 0, 1); return lerp(b, a, h) + k * h * (1 - h); }
/* keyed track: flat list [t, v, mode, t, v, mode ...]; mode of a key = easing of the segment ENDING there
