  const walkW = 1 - sstep(5.7, 6.4, t);
  const ph = TAU * (t - 1) / 3;
  /* --- pelvis --- */
  let bump = 0; for (let i = 0; i < WALK_FALLS.length; i++) bump += walkBump(t - WALK_FALLS[i]);
  const gx = t < 6 ? 40 - WALK_SPEED * t : TR.gx(t);
  const gz = 1.3 * Math.sin(ph) * walkW + TR.pz(t);
  const py = lerp(TR.py(t), 17.1 - 1.3 * bump, walkW);
  const pitch = lerp(TR.pitch(t), 6 + 3.5 * bump, walkW) * DEG;
  const yawT = TR.yaw(t) * (1 - walkW) * DEG;
  const yawWalk = -7 * DEG * Math.cos(ph) * walkW;
  const rollWalk = 3 * DEG * Math.sin(ph) * walkW;
