  const pel = [gx, py + breathe, gz];
  P.G = [gx, 0, gz]; P.pel = pel;
  P.bq[B.PELVIS] = qPel; P.bp[B.PELVIS] = vadd(pel, qrot(qPel, [0, -1, 0]));
  /* --- spine / chest / head --- */
  const counter = 11 * DEG * Math.cos(TAU * (t - 1 - 0.15) / 3) * walkW;
  const qSp = qmul(qmul(qPel, qaxis(Yax, 0.35 * yawT + counter * 0.4)), qaxis(Zax, -0.35 * pitch));
  const spB = vadd(pel, qrot(qPel, [0, 1, 0]));
  P.bq[B.SPINE] = qSp; P.bp[B.SPINE] = spB;
  const qCh = qmul(qmul(qSp, qaxis(Yax, 0.40 * yawT + counter * 0.6)), qaxis(Zax, -0.35 * pitch));
  const chB = vadd(spB, qrot(qSp, [0, BONE_LEN[B.SPINE], 0]));
  P.bq[B.CHEST] = qCh; P.bp[B.CHEST] = chB;
  const hdPitch = (-0.45 * pitch) + TR.headPitch(t) * DEG + 4 * DEG * Math.sin(t * 0.9);
  const qHd = qmul(qmul(qCh, qaxis(Yax, 0.25 * yawT - counter * 0.5)), qaxis(Zax, -hdPitch));
  P.bq[B.HEAD] = qHd; P.bp[B.HEAD] = vadd(chB, qrot(qCh, [0, BONE_LEN[B.CHEST] + 0.8, 0]));
  /* --- arms (IK toward free / world-anchored targets) --- */
  const yawC = yawP + 0.75 * yawT + counter;
  const Fh = [-Math.cos(yawC), 0, Math.sin(yawC)], Rh = [-Math.sin(yawC), 0, -Math.cos(yawC)];
  for (let side = 0; side < 2; side++) {          /* 0 = left, 1 = right */
    const sg = side ? 1 : -1;
    const sh = vadd(chB, qrot(qCh, [0, SHOULDER_Y, sg * SHOULDER_Z]));
    /* free target */
    const swing = 17 * DEG * Math.cos(TAU * (t - 1 - 0.35) / 3) * (side ? 1 : -1);
    const fw = [14.2 * Math.sin(swing) + 0.8, -14.2 * Math.cos(swing), sg * 1.2];
    const fk = side ? ARM_R(t) : ARM_L(t);
    const f = [lerp(fk[0], fw[0], walkW), lerp(fk[1], fw[1], walkW), lerp(fk[2], fw[2], walkW)];
    let tgt = vadd(sh, vadd(vscale(Fh, f[0]), vadd([0, f[1], 0], vscale(Rh, f[2]))));
    let pole = vadd(vadd(vscale(Fh, -0.55), vscale(Rh, sg * 0.55)), [0, -0.6, 0]);
    let fistTip = null, wWorld = 0;
    if (side === 1) {                              /* right fist slam, planted until 10.5 */
      wWorld = t < 7.5 ? Math.pow(clamp((t - 7.28) / 0.22, 0, 1), 2) : 1 - sstep(10.5, 11.1, t);
      if (wWorld > 0) fistTip = [SLAM_POS[0], terrainH(SLAM_POS[0], SLAM_POS[2]) + 1.25, SLAM_POS[2]];
    } else {                                       /* left arm sweep */
      wWorld = pulse(17.0, 18.2, 19.6, 20.9, t);
      if (wWorld > 0) { const a = TR.swA(t) * DEG, r = TR.swR(t); fistTip = [gx - r * Math.cos(a), TR.swY(t) - 1.2, gz + r * Math.sin(a)]; }
    }
    if (fistTip) {
      let wt = vadd(fistTip, [0, 2.0, 0]);
      for (let it = 0; it < 2; it++) {             /* seat the fist tip, not the wrist, on the target */
        const r0 = ik2(sh, wt, UPPER_ARM, FOREARM, pole);
        wt = vsub(fistTip, vscale(vnorm(vsub(r0.end, r0.mid)), FIST));
      }
      tgt = vlerp(tgt, wt, wWorld);
    }
    const r = ik2(sh, tgt, UPPER_ARM, FOREARM, pole);
    const d1 = vnorm(vsub(r.mid, sh)), d2 = vnorm(vsub(r.end, r.mid)), back = vscale(r.bend, -1);
    const ua = side ? B.RUA : B.LUA;
    P.bp[ua] = sh; P.bq[ua] = limbQuat(d1, back);
    P.bp[ua + 1] = r.mid; P.bq[ua + 1] = limbQuat(d2, back);
    P.bp[ua + 2] = r.end; P.bq[ua + 2] = P.bq[ua + 1];
  }
  /* --- legs (IK to planted / stepping ankles) --- */
  const FhP = [-Math.cos(yawP), 0, Math.sin(yawP)], RhP = [-Math.sin(yawP), 0, -Math.cos(yawP)];
  for (let side = 0; side < 2; side++) {
    const sg = side ? 1 : -1;
    const hip = vadd(pel, qrot(qPel, [0, -0.5, sg * HIP_Z]));
    let ax, lift = 0, toeDown = 0;
    if (side === 0) {
      if (t < 4) { const w = footWalk(L_PLANTS, t); ax = w[0]; lift = w[1]; toeDown = -16 * DEG * Math.sin(PI * w[2]); }
      else {
        ax = TR.lfx(t);
        lift = 1.7 * Math.sin(PI * clamp((t - 12.2) / 0.6, 0, 1)) + 1.4 * Math.sin(PI * clamp((t - 15.15) / 0.75, 0, 1)) + 0.25 * pulse(12.8, 13.0, 15.1, 15.3, t);
        toeDown = TR.lfPitch(t) * DEG;
      }
    } else {
      const w = footWalk(R_PLANTS, t); ax = w[0]; lift = w[1]; toeDown = -16 * DEG * Math.sin(PI * w[2]);
    }
    const az = -sg * STANCE_Z;                     /* world z: left = +, right = - */
    const ank = [ax, terrainH(ax, az) + ANKLE_H + lift, az];
    const pole = vadd(FhP, vscale(RhP, sg * 0.12));
    const r = ik2(hip, ank, THIGH, SHIN, pole);
    const d1 = vnorm(vsub(r.mid, hip)), d2 = vnorm(vsub(r.end, r.mid));
    const th = side ? B.RTH : B.LTH;
    P.bp[th] = hip; P.bq[th] = limbQuat(d1, r.bend);
    P.bp[th + 1] = r.mid; P.bq[th + 1] = limbQuat(d2, r.bend);
    const qFoot = qmul(qaxis(Yax, PI + yawP * 0.5), qaxis(Zax, -toeDown));
    P.bq[th + 2] = qFoot; P.bp[th + 2] = vadd(r.end, qrot(qFoot, [-1.2, -0.6, 0]));
    if (side === 0) { P.ankL = r.end; P.kneeL = r.mid; } else { P.ankR = r.end; P.kneeR = r.mid; }
  }
  for (let i = 0; i < NB; i++) {
    P.tip[i] = vadd(P.bp[i], qrot(P.bq[i], vscale(BONE_DIR[i], BONE_LEN[i])));
    P.charge[i] = boneCharge(i, t);
  }
  return P;
}
/* memoized pose lookup */
const _tpCache = new Map();
function titanPose(t) {
  let p = _tpCache.get(t);
  if (!p) { if (_tpCache.size > 600) _tpCache.clear(); p = titanCompute(t); _tpCache.set(t, p); }
  return p;
}
function boneLocal(P, bone, loc) { return vadd(P.bp[bone], qrot(P.bq[bone], loc)); }
function wpPos(P, i) { return boneLocal(P, WP_BONE[i], WP_LOCAL[i]); }
function pinPos(P, i) { return boneLocal(P, PIN_BONE[i], PIN_LOCAL[i]); }
function chestCenter(P) { return boneLocal(P, B.CHEST, [0, 3.5, 0]); }
function fistCenter(P, side) { const b = side ? B.RFI : B.LFI; return boneLocal(P, b, [0, -1.25, 0]); }
function avgCharge(t) { let s = 0; for (let i = 0; i < NB; i++) s += boneCharge(i, t); return s / NB; }

