function f(v) { return '(' + v.map(x => x.toFixed(2)).join(', ') + ')'; }
function show(t) {
  const P = titanPose(t);
  print('t=' + t.toFixed(2), 'pel', f(P.pel), 'chestC', f(chestCenter(P)), 'headTip', f(P.tip[B.HEAD]),
    '\n    fistL', f(fistCenter(P, 0)), 'fistR', f(fistCenter(P, 1)), 'tipR', f(P.tip[B.RFI]), 'tipL', f(P.tip[B.LFI]),
    '\n    ankL', f(P.ankL), 'kneeL', f(P.kneeL), 'ankR', f(P.ankR), 'kneeR', f(P.kneeR),
    '\n    W1', f(wpPos(P, 0)), 'W2', f(wpPos(P, 1)), 'W3', f(wpPos(P, 2)), 'pin1', f(pinPos(P, 0)), 'pin3', f(pinPos(P, 2)));
}
[0, 0.99, 1.0, 2.5, 3.0, 3.3, 4.0, 5.0, 6.0, 7.25, 7.5, 9.0, 10.5, 12.0, 12.4, 13.0, 14, 16, 18.5, 18.8, 19.0, 19.2, 19.3, 22.5, 25.0, 25.3, 27, 29.5].forEach(show);
// continuity check: max bone base speed over the timeline
let worst = 0, wt = 0, wb = 0;
for (let t = 0.004; t < 33; t += 1 / 240) {
  const a = titanPose(t), b = titanPose(t + 1 / 240);
  for (let i = 0; i < NB; i++) { const v = vdist(a.tip[i], b.tip[i]) * 240; if (v > worst) { worst = v; wt = t; wb = i; } }
}
print('max tip speed', worst.toFixed(1), 'm/s at t=' + wt.toFixed(3), BONE_NAMES[wb]);
// limb stretch check (IK clamped?)
let minKnee = 99, tk = 0;
for (let t = 12.5; t < 15.5; t += 1 / 240) { const P = titanPose(t); if (P.kneeL[1] < minKnee) { minKnee = P.kneeL[1]; tk = t; } }
print('min left knee y', minKnee.toFixed(2), 'at', tk.toFixed(3), ' kneeY@13.0', titanPose(13.0).kneeL[1].toFixed(2));
for (let t = 18.5; t <= 19.35; t += 0.05) { const P = titanPose(t); print('sweep t=' + t.toFixed(2), 'fistL', f(fistCenter(P, 0)), 'tip', f(P.tip[B.LFI])); }

