/* =====================================================================
   HUNTER — chest path. Closed-form pieces (splines through time-stamped
   waypoints, constant-length swing arcs around the tether pins, ballistic
   drops) that reach every event of the table on time. Motion time only.
   ===================================================================== */
const HUNTER_START = [-40, 0, 10];
const RUN_H = 1.3;                                 /* chest height above the ground while running */
function G3(x, z, h) { return [x, terrainH(x, z) + (h === undefined ? RUN_H : h), z]; }

/* C1 spline through time-stamped waypoints {t, p, g, m}:
   p = point or function(t)->point (so a waypoint can ride on a Titan bone), g = 1 when on the ground,
   m = optional explicit velocity (e.g. [0,0,0] for a stop) */
function makeSpline(pts) {
  const n = pts.length;
  function P(i, t) { const p = pts[i].p; return typeof p === 'function' ? p(t) : p; }
  function f(t) {
    if (t <= pts[0].t) return P(0, t).slice();
    if (t >= pts[n - 1].t) return P(n - 1, t).slice();
    let i = 0; while (t > pts[i + 1].t) i++;
    const t0 = pts[i].t, t1 = pts[i + 1].t, h = t1 - t0, u = (t - t0) / h;
    const p0 = P(i, t), p1 = P(i + 1, t);
    let m0, m1;
    if (pts[i].m) m0 = pts[i].m; else if (i > 0) m0 = vscale(vsub(p1, P(i - 1, t)), 1 / (t1 - pts[i - 1].t)); else m0 = vscale(vsub(p1, p0), 1 / h);
    if (pts[i + 1].m) m1 = pts[i + 1].m; else if (i < n - 2) m1 = vscale(vsub(P(i + 2, t), p0), 1 / (pts[i + 2].t - t0)); else m1 = vscale(vsub(p1, p0), 1 / h);
    const u2 = u * u, u3 = u2 * u, h00 = 2 * u3 - 3 * u2 + 1, h10 = (u3 - 2 * u2 + u) * h, h01 = -2 * u3 + 3 * u2, h11 = (u3 - u2) * h;
    const r = [h00 * p0[0] + h10 * m0[0] + h01 * p1[0] + h11 * m1[0], h00 * p0[1] + h10 * m0[1] + h01 * p1[1] + h11 * m1[1], h00 * p0[2] + h10 * m0[2] + h01 * p1[2] + h11 * m1[2]];
    const g0 = pts[i].g || 0, g1 = pts[i + 1].g || 0;
    if (g0 > 0 || g1 > 0) {
      const g = g0 + (g1 - g0) * (u * u * (3 - 2 * u));
      const hh = (pts[i].h === undefined ? RUN_H : pts[i].h) + ((pts[i + 1].h === undefined ? RUN_H : pts[i + 1].h) - (pts[i].h === undefined ? RUN_H : pts[i].h)) * u;
      r[1] = lerp(r[1], terrainH(r[0], r[2]) + hh, g);
    }
    return r;
  }
  f.t0 = pts[0].t; f.t1 = pts[n - 1].t;
  return f;
}
/* scalar C1 spline through keys [[t, v], ...] */
function hermite1(k) {
  const n = k.length;
  return function (t) {
    if (t <= k[0][0]) return k[0][1];
    if (t >= k[n - 1][0]) return k[n - 1][1];
    let i = 0; while (t > k[i + 1][0]) i++;
    const h = k[i + 1][0] - k[i][0], u = (t - k[i][0]) / h, p0 = k[i][1], p1 = k[i + 1][1];
    const m0 = i > 0 ? (p1 - k[i - 1][1]) / (k[i + 1][0] - k[i - 1][0]) : (p1 - p0) / h;
    const m1 = i < n - 2 ? (k[i + 2][1] - p0) / (k[i + 2][0] - k[i][0]) : (p1 - p0) / h;
    const u2 = u * u, u3 = u2 * u;
    return (2 * u3 - 3 * u2 + 1) * p0 + (u3 - 2 * u2 + u) * h * m0 + (-2 * u3 + 3 * u2) * p1 + (u3 - u2) * h * m1;
  };
}
function ballistic(p0, t0, p1, t1) {                /* projectile from p0@t0 that lands on p1@t1 */
  const T = t1 - t0;
  const v0 = [(p1[0] - p0[0]) / T, (p1[1] - p0[1] + 0.5 * GRAV * T * T) / T, (p1[2] - p0[2]) / T];
  const f = function (t) { const a = t - t0; return [p0[0] + v0[0] * a, p0[1] + v0[1] * a - 0.5 * GRAV * a * a, p0[2] + v0[2] * a]; };
  f.v0 = v0; return f;
}
function groundClamp(p, minH) { const g = terrainH(p[0], p[2]) + minH; if (p[1] < g + 0.6) p[1] = smax(p[1], g, 0.5); return p; }

const HP = { swingL: [0, 0, 0] };                    /* constant rope lengths of the swing arcs + shared path data */
let hunterPathFn = null;

function buildHunterPathA() {
  /* ---------- swing 1: a rising spiral on the sphere |H - pin1| = L1 around the left shin ---------- */
  const P5 = titanPose(5.0);
  const pin5 = pinPos(P5, 0), w1 = wpPos(P5, 0);
  const strike1 = vadd(w1, [0.3, 0.4, 1.6]);
  const rel = vsub(strike1, pin5), L1 = vlen(rel);
  HP.swingL[0] = L1;
  const thS = Math.atan2(rel[2], rel[0]), dTh = TAU + 12 * DEG, th0 = thS + 12 * DEG;      /* 372 deg of wrap by the strike */
  const phS = Math.asin(rel[1] / L1);
  const pin33 = pinPos(titanPose(3.3), 0);
  const ph0 = Math.asin(clamp((4.2 - pin33[1]) / L1, -1, 1));
  const phi = hermite1([[3.3, ph0], [3.9, -6 * DEG], [4.35, 38 * DEG], [4.7, 50 * DEG], [5.0, phS]]);
  function F(s) { return s <= 0 ? 1.2 * s : 1.2 * s - 0.75 * s * s + 0.55 * s * s * s; }       /* normalized swept angle */
  function swing1(t) {
    const tt = Math.min(t, 5.0), pin = pinPos(titanPose(tt), 0);
    const th = th0 - dTh * F((tt - 3.3) / 1.7), ph = phi(tt), c = Math.cos(ph);
    return [pin[0] + L1 * c * Math.cos(th), pin[1] + L1 * Math.sin(ph), pin[2] + L1 * c * Math.sin(th)];
  }
