function buildHunterPathA() {
  /* ---------- swing 1: a rising spiral on the sphere |H - pin1| = L1 around the left shin ---------- */
  const P5 = titanPose(5.0);
  const pin5 = pinPos(P5, 0), w1 = wpPos(P5, 0);
  const strike1 = vadd(w1, [0.3, 0.4, 1.6]);
  const rel = vsub(strike1, pin5), L1 = vlen(rel);
  HP.swingL[0] = L1;
  const thS = Math.atan2(rel[2], rel[0]), dTh = TAU + 12 * DEG, th0 = thS + 12 * DEG;      /* 372 deg of wrap by the strike */
  const phS = Math.asin(rel[1] / L1);
  const pin33 = pinPos(titanPose(3.3), 0);
  const ph0 = Math.asin(clamp((4.2 - pin33[1]) / L1, -1, 1));
  const phi = hermite1([[3.3, ph0], [3.9, -6 * DEG], [4.35, 38 * DEG], [4.7, 50 * DEG], [5.0, phS]]);
  function F(s) { return s <= 0 ? 1.2 * s : 1.2 * s - 0.75 * s * s + 0.55 * s * s * s; }       /* normalized swept angle */
  function swing1(t) {
    const tt = Math.min(t, 5.0), pin = pinPos(titanPose(tt), 0);
    const th = th0 - dTh * F((tt - 3.3) / 1.7), ph = phi(tt), c = Math.cos(ph);
    return [pin[0] + L1 * c * Math.cos(th), pin[1] + L1 * Math.sin(ph), pin[2] + L1 * c * Math.sin(th)];
  }
  HP.swing1 = swing1; HP.strikePos = [swing1(5.0)];
  /* ---------- approach sprint ---------- */
  const e33 = swing1(3.3), runEnd = [e33[0], 0, e33[2]];
  HP.runSpeed = Math.hypot(runEnd[0] - HUNTER_START[0], runEnd[2] - HUNTER_START[2]) / 3.3;
  function run0(t) { const u = t / 3.3; return G3(lerp(HUNTER_START[0], runEnd[0], u), lerp(HUNTER_START[2], runEnd[2], u)); }
  /* ---------- kick off the knee, drop, sprint clear of the slam, turn, tether 2 ---------- */
  const pin2a = pinPos(titanPose(10.5), 1);
  /* swing 2 geometry (needs the strike standoff at W2) */
  const P12 = titanPose(12.0), pin2s = pinPos(P12, 1), w2 = wpPos(P12, 1);
  const strike2 = vadd(w2, vadd(qrot(P12.bq[B.CHEST], [1.5, 0.9, 0.2]), [0, 0.3, 0]));
  const L2 = vdist(strike2, pin2s); HP.swingL[1] = L2;
  const gy = terrainH(pin2a[0] - 4, pin2a[2] - 1) + RUN_H + 0.1, dy = gy - pin2a[1];
  const hr = Math.sqrt(Math.max(1, L2 * L2 - dy * dy));
  const toH = vnorm([-7.5 - pin2a[0], 0, -4 - pin2a[2]]);
  const ps2 = [pin2a[0] + toH[0] * hr, gy, pin2a[2] + toH[2] * hr];
  const splB = makeSpline([
    { t: 5.0, p: HP.strikePos[0] }, { t: 5.3, p: [14.6, 8.4, 9.9] }, { t: 5.6, p: [11.3, 5.0, 8.4] },
    { t: 6.05, p: G3(8.5, 6.0), g: 1, h: 1.0 }, { t: 6.5, p: G3(SLAM_POS[0], SLAM_POS[2]), g: 1 }, { t: 7.0, p: G3(-3.5, -3), g: 1 },
    { t: 7.5, p: G3(-9.5, -7.5), g: 1 }, { t: 8.2, p: G3(-14.5, -10), g: 1 }, { t: 9.0, p: G3(-15, -8.5), g: 1, m: [0.6, 0, 1.2] },
    { t: 9.3, p: G3(-13.8, -7.6), g: 1 }, { t: 10.0, p: G3(-7.5, -4), g: 1 }, { t: 10.5, p: ps2, g: 1, h: RUN_H + 0.1 }
  ]);
  /* ---------- swing 2: hoisted by the rising forearm, then up to the shoulder, on |H - pin2| = L2 ---------- */
  const uA = vnorm(vsub(ps2, pin2a)), uC = vnorm(vsub(strike2, pin2s));
  const dirS = makeSpline([{ t: 10.5, p: uA }, { t: 11.25, p: vnorm([-0.25, -0.95, -0.2]) }, { t: 12.0, p: uC }, { t: 12.4, p: vnorm([-0.45, -0.85, -0.3]) }]);
  function swing2(t) { const pin = pinPos(titanPose(t), 1), u = vnorm(dirS(Math.min(t, 12.4))); return groundClamp(vmad(pin, u, L2), 1.15); }
  HP.swing2 = swing2; HP.strikePos[1] = swing2(12.0);
  /* ---------- drop from the forearm, land at 13.5, circle, charge in, get swept at 19.0 ---------- */
  const land2 = G3(5, -15, 1.0);
  const bal2 = ballistic(swing2(12.4), 12.4, land2, 13.5);
  const P19 = titanPose(T_SWEEP_HIT), fc = fistCenter(P19, 0), fv = vnorm(vsub(fistCenter(titanPose(19.02), 0), fistCenter(titanPose(18.98), 0)));
  const hit = [fc[0] + fv[0] * 2.7, 0, fc[2] + fv[2] * 2.7]; hit[1] = terrainH(hit[0], hit[2]) + 1.9;
  HP.hitPos = hit; HP.fistDir = fv;
  const splC = makeSpline([
    { t: 13.5, p: land2, g: 1, h: 1.0 }, { t: 14.3, p: G3(0, -17.5), g: 1 }, { t: 15.2, p: G3(-6, -14), g: 1 }, { t: 16.0, p: G3(-10, -8), g: 1 },
    { t: 17.0, p: G3(-8.5, -3), g: 1 }, { t: 18.0, p: G3(hit[0] - 3.4, hit[2] - 0.8), g: 1 }, { t: 18.6, p: G3(hit[0] - 1.2, hit[2] - 0.2), g: 1 }, { t: 19.0, p: hit }
  ]);
  HP.pathA = function (t) {
    if (t < 3.05) return run0(t);
    if (t < 3.3) return vlerp(run0(t), swing1(t), sstep(3.05, 3.3, t));
    if (t < 5.0) return groundClamp(swing1(t), 1.15);
    if (t < 10.5) return splB(t);
    if (t < 12.3) return swing2(t);
    if (t < 12.5) return vlerp(swing2(t), bal2(t), sstep(12.3, 12.5, t));
    if (t < 13.5) return bal2(t);
    return splC(Math.min(t, T_SWEEP_HIT));
  };
}

/* second half: needs the ragdoll's resting place (upXZ) */
function buildHunterPathB(upXZ, lieDir) {
  HP.up = upXZ; HP.lieDir = lieDir;
  const Q = [-2, 0, -13], d = vnorm([Q[0] - upXZ[0], 0, Q[2] - upXZ[2]]), dist = Math.hypot(Q[0] - upXZ[0], Q[2] - upXZ[2]);
  function along(s) { const k = Math.min(s, dist * 0.92); return G3(upXZ[0] + d[0] * k, upXZ[2] + d[2] * k); }
  function w3off(off) { return function (t) { return vadd(wpPos(titanPose(t), 2), off); }; }
  function w3loc(loc) { return function (t) { const P = titanPose(t); return vadd(wpPos(P, 2), qrot(P.bq[B.CHEST], loc)); }; }
  const upG = function (t) { return [upXZ[0], terrainH(upXZ[0], upXZ[2]) + lerp(0.36, RUN_H, smooth01((t - T_RAG_END) / 1.0)), upXZ[2]]; };
  const strikeA = w3loc([1.75, 0.15, 0.25]), strikeB = w3loc([1.7, 0.2, 0.2]);
  HP.strikePos[2] = strikeA(27.0); HP.strikePos[3] = strikeB(T_KILL);
  const splD = makeSpline([
    { t: 22.5, p: G3(upXZ[0], upXZ[2]), g: 1, m: [0, 0, 0] }, { t: 23.5, p: along(9.5), g: 1 }, { t: 23.8, p: along(13.6), g: 1 }, { t: 24.5, p: along(23.5), g: 1 },
    { t: 25.2, p: w3off([-13, -17, -11.5]) }, { t: 25.9, p: w3off([-9, -8, -7.5]) }, { t: 26.5, p: w3off([-5, -3, -3.5]) }, { t: 27.0, p: strikeA },
    { t: 27.5, p: w3loc([2.6, -0.3, -1.6]) }, { t: 28.1, p: w3loc([3.1, 0.5, -2.6]), m: [0, 0, 0] }, { t: 28.8, p: w3loc([2.9, -0.2, -1.0]) }, { t: T_KILL, p: strikeB }
  ]);
  const land3 = G3(-8, 7, 0.95);
  const bal3 = ballistic(HP.strikePos[3], T_KILL, land3, T_HUNTER_LAND);
  const splE = makeSpline([
    { t: 31.5, p: land3, g: 1, h: 0.95 }, { t: 31.9, p: G3(-9.9, 8.1, 0.75), g: 1, h: 0.75 }, { t: 32.3, p: G3(-11.3, 9.0, 1.0), g: 1, h: 1.0 },
    { t: 33.0, p: G3(-11.9, 9.5), g: 1, m: [0, 0, 0] }, { t: 33.7, p: G3(-11.9, 9.5), g: 1, m: [0, 0, 0] },
    { t: 36.0, p: G3(-2.5, 13), g: 1, m: [0, 0, 0] }, { t: 40.5, p: G3(-2.5, 13), g: 1, m: [0, 0, 0] }
  ]);
  HP.pathB = function (t) {
    if (t < T_RAG_BLEND_END) return upG(t);
    if (t < T_KILL) return splD(t);
    if (t < T_HUNTER_LAND) return bal3(t);
    return splE(t);
  };
  hunterPathFn = function (t) { return t <= T_SWEEP_HIT ? HP.pathA(t) : (t < T_RAG_END ? HP.pathA(T_SWEEP_HIT) : HP.pathB(t)); };
}
/* grounded weight of the animated hunter (1 on the grass, 0 in the air) */
const GROUND_SPANS = [[-1, 3.07], [6.03, 10.52], [13.48, 18.88], [21.4, 24.6], [31.48, 99]];
function groundedAt(t) { let g = 0; for (let i = 0; i < GROUND_SPANS.length; i++) g = Math.max(g, pulse(GROUND_SPANS[i][0] - 0.04, GROUND_SPANS[i][0] + 0.08, GROUND_SPANS[i][1] - 0.06, GROUND_SPANS[i][1] + 0.06, t)); return g; }
function tetherAt(t) { for (let i = 0; i < 3; i++) if (t >= TETHER[i].attach && t < TETHER[i].release) return i; return -1; }

