load('p01_core.js'); load('p02_titan.js'); load('p03a_hpath.js');
function f(v) { return '(' + v.map(x => x.toFixed(2)).join(', ') + ')'; }
buildHunterPathA();
print('L1', HP.swingL[0].toFixed(3), 'L2', HP.swingL[1].toFixed(3), 'runSpeed', HP.runSpeed.toFixed(2), 'hit', f(HP.hitPos), 'fistDir', f(HP.fistDir));
print('strike1', f(HP.strikePos[0]), 'W1', f(wpPos(titanPose(5), 0)), 'strike2', f(HP.strikePos[1]), 'W2', f(wpPos(titanPose(12), 1)));
function segDist(p, a, b) { const ab = vsub(b, a), t = clamp(vdot(vsub(p, a), ab) / vdot(ab, ab), 0, 1); return vdist(p, vmad(a, ab, t)); }
let maxV = 0, tv = 0, minClr = 99, tc = 0, bc = 0, minG = 99, tg = 0, lenErr = 0;
for (let t = 0; t < 19.0; t += 1 / 240) {
  const p = HP.pathA(t), q = HP.pathA(t + 1 / 240), v = vdist(p, q) * 240;
  if (v > maxV) { maxV = v; tv = t; }
  const P = titanPose(t);
  for (let i = 0; i < NB; i++) { const c = segDist(p, P.bp[i], P.tip[i]) - BONE_RAD[i]; if (c < minClr && !(t > 4.9 && t < 5.1) && !(t > 11.9 && t < 12.1) && t < 18.9) { minClr = c; tc = t; bc = i; } }
  if (t >= 3.0 && t < 9) { const g = Math.hypot(p[0] - P.G[0], p[2] - P.G[2]); if (g < minG) { minG = g; tg = t; } }
  if (t >= 3.3 && t <= 5.0) lenErr = Math.max(lenErr, Math.abs(vdist(p, pinPos(P, 0)) - HP.swingL[0]));
