for (let t = 0; t <= 19.001; t += 0.1) {
  const p = HP.pathA(t), q = HP.pathA(t + 0.01), P = titanPose(t);
  if ((t > 2.85 && t < 6.6) || (t > 8.9 && t < 13.7) || t > 18.4 || Math.abs(t - Math.round(t)) < 0.01)
    print(t.toFixed(2), f(p), 'v=' + (vdist(p, q) * 100).toFixed(1), 'h=' + (p[1] - terrainH(p[0], p[2])).toFixed(2), 'pin1', f(pinPos(P, 0)), 'G', P.G[0].toFixed(1));
}

