/* =====================================================================
   HUNTER — body. 15 joints; every body part is drawn between joints, so
   the animated pose, the Verlet ragdoll and the blend share one format.
   ===================================================================== */
const NJ = 15;
const J = { HEAD: 0, CHEST: 1, PELVIS: 2, SHL: 3, SHR: 4, ELL: 5, ELR: 6, HAL: 7, HAR: 8, HIPL: 9, HIPR: 10, KNL: 11, KNR: 12, FTL: 13, FTR: 14 };
const UARM = 0.30, LARM = 0.29, ULEG = 0.46, LLEG = 0.45, TORSO = 0.44, NECK = 0.27, SH_W = 0.2, HIP_W = 0.1, BLADE_LEN = 1.15;
const UPV = [0, 1, 0];
const PH_DT = 1 / 120;
const runPhaseTab = new Float32Array(Math.round(41 / PH_DT) + 2);
let runPhaseN = 0, runPhaseAcc = 0;
function hunterVel(t) { const a = hunterPathFn(t), b = hunterPathFn(t - 0.03); return [(a[0] - b[0]) / 0.03, (a[1] - b[1]) / 0.03, (a[2] - b[2]) / 0.03]; }
function buildRunPhase(tEnd) {                     /* stride phase = integral of a speed-dependent cadence (precomputed table) */
  const n = Math.min(runPhaseTab.length - 1, Math.round(tEnd / PH_DT));
  for (; runPhaseN <= n; runPhaseN++) {
    const t = runPhaseN * PH_DT; runPhaseTab[runPhaseN] = runPhaseAcc;
    const v = hunterVel(t), sp = Math.hypot(v[0], v[2]);
    runPhaseAcc += TAU * (0.9 + 0.105 * Math.min(sp, 18)) * PH_DT * groundedAt(t) * sstep(0.3, 1.5, sp);
  }
}
function runPhase(t) { const x = clamp(t / PH_DT, 0, runPhaseTab.length - 2), i = Math.floor(x); return lerp(runPhaseTab[i], runPhaseTab[i + 1], x - i); }
function tetherWindowW(t, lead, tail) { let w = 0; for (let i = 0; i < 3; i++) w = Math.max(w, pulse(TETHER[i].fire - lead, TETHER[i].fire - 0.02, TETHER[i].release - 0.04, TETHER[i].release + tail, t)); return w; }
function tetherIndexNear(t) { let b = 0; for (let i = 0; i < 3; i++) if (t >= TETHER[i].fire - 0.3) b = i; return b; }
function frameFromJoints(j) {
  const u = vnorm(vsub(j[J.CHEST], j[J.PELVIS])); let r = vsub(j[J.SHR], j[J.SHL]); r = vnorm(vsub(r, vscale(u, vdot(r, u))));
  return { u: u, r: r, X: vcross(u, r) };
}

function hunterPoseKin(t) {
  const c = hunterPathFn(t), v = hunterVel(t), sp = vlen(v);
  const P = titanPose(t), tc = chestCenter(P);
  const gW = groundedAt(t), twS = tetherWindowW(t, -0.3, 0.15) , aimW = tetherWindowW(t, 0.18, 0.25);
  const ti = tetherIndexNear(t), pin = pinPos(P, ti);
  const face = vnorm([tc[0] - c[0], 0, tc[2] - c[2]]);
  const vh = [v[0], 0, v[2]], vdir = sp > 0.5 ? vscale(v, 1 / sp) : face;
  let f = vnorm(vadd(vh, vscale(face, 2.5)));
  const toPin = vnorm(vsub(pin, c));
  const getup = (t >= T_RAG_END - 0.01 && t < T_RAG_BLEND_END) ? clamp(t - T_RAG_END, 0, 1) : -1;
  /* body up axis */
  const lean = clamp(sp * 2.0, 0, 34) * DEG;
  const uG = vadd(vscale(f, Math.sin(lean)), [0, Math.cos(lean), 0]);
  const uT = vnorm(vadd(vadd(vscale(toPin, 0.75), [0, 0.55, 0]), vscale(vdir, -0.2)));
  const uA = vnorm(vadd(UPV, vscale(vh, 0.012)));
