  let u = vnorm(vadd(vadd(vscale(uG, gW), vscale(uT, wT)), vscale(uA, wA)));
  if (getup >= 0) u = vnorm(vlerp(vadd(HP.lieDir, [0, 0.35, 0]), UPV, smooth01(getup * 1.15)));
  let X = vsub(f, vscale(u, vdot(f, u))); if (vlen(X) < 1e-4) X = vsub(face, vscale(u, vdot(face, u))); X = vnorm(X);
