    const a = TAU * smooth01((t - T_HUNTER_LAND) / 0.8), ca = Math.cos(a), sa = Math.sin(a);
    const u2 = vadd(vscale(u, ca), vscale(X, sa)), X2 = vsub(vscale(X, ca), vscale(u, sa)); u = u2; X = X2;
  }
  const r = vcross(X, u);
  const fh = vnorm([f[0], 0, f[2]]);
  const j = new Array(NJ);
  const pel = vmad(c, u, -TORSO);
  j[J.CHEST] = c; j[J.PELVIS] = pel; j[J.HEAD] = vadd(vmad(c, u, NECK), vscale(X, 0.03));
  const shL = vadd(vmad(c, r, -SH_W), vscale(u, 0.03)), shR = vadd(vmad(c, r, SH_W), vscale(u, 0.03));
  const hipL = vmad(pel, r, -HIP_W), hipR = vmad(pel, r, HIP_W);
  j[J.SHL] = shL; j[J.SHR] = shR; j[J.HIPL] = hipL; j[J.HIPR] = hipR;
