  const ph = runPhase(t), idle = 1 - sstep(0.4, 2.0, sp), k = clamp(sp / 9, 0.25, 1.15), mv = 1 - idle;
  function footG(hip, phi, side) {
    const sw = Math.sin(phi), lf = Math.max(0, Math.cos(phi)), st = 0.55 * k * mv * sw - 0.04;
    const x = hip[0] + fh[0] * st + r[0] * side * 0.03, z = hip[2] + fh[2] * st + r[2] * side * 0.03;
    return [x, terrainH(x, z) + 0.09 + 0.3 * k * lf * mv, z];
  }
  function handG(sh, phi, side) {
    const sa = Math.sin(phi);
    return vadd(sh, vadd(vadd(vscale(fh, 0.3 * k * sa * mv + 0.04 * idle), [0, -0.36 + 0.1 * Math.abs(sa) * mv * k - 0.14 * idle, 0]), vscale(r, side * (0.09 - 0.03 * idle))));
