  const tA = [vadd(vadd(vmad(hipL, u, -0.62), vscale(X, -0.22)), vscale(r, -0.05)), vadd(vadd(vmad(hipR, u, -0.5), vscale(X, 0.2)), vscale(r, 0.05)),
              vadd(vadd(vmad(shL, r, -0.3), vscale(u, -0.15)), vscale(X, 0.1)), vadd(vadd(vmad(shR, r, 0.3), vscale(u, -0.2)), vscale(X, -0.1))];
  const tT = [vadd(vadd(vmad(hipL, u, -0.78), vscale(vdir, -0.28)), vscale(r, -0.04)), vadd(vadd(vadd(vmad(hipR, u, -0.6), vscale(vdir, -0.1)), vscale(X, 0.2)), vscale(r, 0.04)),
              vmad(shL, toPin, 0.56), vadd(vadd(vmad(shR, u, -0.3), vscale(X, -0.2)), vscale(r, 0.22))];
  const tg = new Array(4);
  for (let i = 0; i < 4; i++) tg[i] = [tG[i][0] * gW + tA[i][0] * wA + tT[i][0] * wT, tG[i][1] * gW + tA[i][1] * wA + tT[i][1] * wT, tG[i][2] * gW + tA[i][2] * wA + tT[i][2] * wT];
  if (t >= T_HUNTER_LAND && t < T_HUNTER_LAND + 0.8) {         /* tuck while rolling */
    const w = pulse(T_HUNTER_LAND, T_HUNTER_LAND + 0.12, T_HUNTER_LAND + 0.62, T_HUNTER_LAND + 0.8, t);
    tg[0] = vlerp(tg[0], vadd(vmad(hipL, u, -0.4), vscale(X, 0.25)), w); tg[1] = vlerp(tg[1], vadd(vmad(hipR, u, -0.4), vscale(X, 0.25)), w);
    tg[2] = vlerp(tg[2], vadd(vmad(shL, X, 0.3), vscale(u, -0.15)), w); tg[3] = vlerp(tg[3], vadd(vmad(shR, X, 0.3), vscale(u, -0.15)), w);
  }
  if (getup >= 0) {                                 /* push up off the grass, gather the feet, stand */
    const e = smooth01(getup), hw = 1 - sstep(0.45, 0.85, getup);
    const gp = function (p) { return [p[0], terrainH(p[0], p[2]) + 0.07, p[2]]; };
    tg[2] = vlerp(tg[2], gp(vadd(vmad(shL, r, -0.12), vscale(fh, 0.18))), hw); tg[3] = vlerp(tg[3], gp(vadd(vmad(shR, r, 0.12), vscale(fh, 0.18))), hw);
    const back = vscale(HP.lieDir, -lerp(0.75, 0.0, e));
    tg[0] = gp(vadd(vadd(pel, back), vscale(r, -0.12))); tg[1] = gp(vadd(vadd(pel, vscale(back, 0.55)), vscale(r, 0.12)));
