  /* ---- strikes: wind up, extend through the weak point ---- */
  let bd = vnorm(vadd(vadd(vscale(X, -0.75 * gW - 0.5 * (1 - gW)), vscale(u, -0.55 * gW + 0.2 * (1 - gW))), vscale(r, 0.25 * gW + 0.7 * (1 - gW))));
