  function footG(hip, phi, side) {
    const sw = Math.sin(phi), lf = Math.max(0, Math.cos(phi)), st = 0.55 * k * mv * sw - 0.04;
    const x = hip[0] + fh[0] * st + r[0] * side * 0.03, z = hip[2] + fh[2] * st + r[2] * side * 0.03;
