    const e = smooth01(getup), hw = 1 - sstep(0.45, 0.85, getup);
    const gp = function (p) { return [p[0], terrainH(p[0], p[2]) + 0.07, p[2]]; };
    tg[2] = vlerp(tg[2], gp(vadd(vmad(shL, r, -0.12), vscale(fh, 0.18))), hw); tg[3] = vlerp(tg[3], gp(vadd(vmad(shR, r, 0.12), vscale(fh, 0.18))), hw);
