/* =====================================================================
   RENDERER, SCENE, SKY, ENVIRONMENT, TERRAIN, GRASS, RAIN
   ===================================================================== */
const COUNTS = { grassBlades: 100000, rainStreaks: 20000, splashes: 600 };
const canvas = document.getElementById('stage');
const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('stage'), antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputEncoding = THREE.sRGBEncoding;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.autoClear = false;
const scene = new THREE.Scene();
const FOG_BASE = new THREE.Color(0x18202b);
scene.background = new THREE.Color(0x0c1016);          /* opaque; the procedural sky dome is drawn over it */
scene.fog = new THREE.FogExp2(FOG_BASE.getHex(), 0.0072);
const camera = new THREE.PerspectiveCamera(40, window.innerWidth / window.innerHeight, 0.1, 2000);
camera.position.set(-70, 6, 50);

/* uniforms shared by the custom shaders (one object per value, referenced by every material) */
const SU = {
  uTime: { value: 0 }, uMt: { value: 0 }, uFlash: { value: 0 }, uWet: { value: 0 },
  uFogColor: { value: new THREE.Color(FOG_BASE.getHex()) }, uFogDensity: { value: 0.0072 },
  uCam: { value: new THREE.Vector3() }, uKeyDir: { value: new THREE.Vector3(-0.45, 0.78, 0.43).normalize() },
  uKeyCol: { value: new THREE.Color(0.62, 0.74, 1.0) }, uAmb: { value: new THREE.Color(0.10, 0.125, 0.16) },
  uALp: { value: [] }, uALi: { value: new Float32Array(6) }, uFlashDir: { value: new THREE.Vector3(0.3, 0.9, 0.2).normalize() },
  uPx: { value: 1 / 540 }                               /* world-units per pixel at unit distance (set per frame) */
};
for (let i = 0; i < 6; i++) SU.uALp.value.push(new THREE.Vector3());
const GLSL_COMMON = `
float terrainH(vec2 p){ return 0.28*sin(0.045*p.x+1.3)*cos(0.038*p.y-0.7) + 0.20*sin(0.09*p.x-0.05*p.y+2.1) + 0.10*sin(0.17*p.y+0.11*p.x); }
float h11(float n){ return fract(sin(n*127.1)*43758.5453123); }
float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453123); }
float vn2(vec2 p){ vec2 i=floor(p), f=fract(p); f=f*f*(3.0-2.0*f); return mix(mix(h21(i),h21(i+vec2(1,0)),f.x), mix(h21(i+vec2(0,1)),h21(i+vec2(1,1)),f.x), f.y); }
float fbm2(vec2 p){ float a=0.5, s=0.0; for(int i=0;i<5;i++){ s+=a*vn2(p); p=p*2.03+vec2(17.3,9.1); a*=0.5; } return s; }
`;
const GLSL_FOG_PARS = `uniform vec3 uFogColor; uniform float uFogDensity; uniform float uFlash;
vec3 applyFog(vec3 c, float d){ float f = 1.0 - exp(-uFogDensity*uFogDensity*d*d); return mix(c, uFogColor*(1.0+uFlash*2.2), clamp(f,0.0,1.0)); }`;
const GLSL_OUT = `
#include <tonemapping_fragment>
#include <encodings_fragment>`;

/* ---------- lights: low ambient fill, one cool shadowed key, lightning flash, arc/blade point lights ---------- */
const ambient = new THREE.AmbientLight(0x8fa6c8, 0.22);
scene.add(ambient);
const keyLight = new THREE.DirectionalLight(0xa6c0ff, 1.25);
keyLight.position.copy(SU.uKeyDir.value).multiplyScalar(120).add(new THREE.Vector3(5, 0, 0));
keyLight.target.position.set(5, 0, 0);
keyLight.castShadow = true;
keyLight.shadow.mapSize.set(2048, 2048);
keyLight.shadow.camera.left = -78; keyLight.shadow.camera.right = 78; keyLight.shadow.camera.top = 78; keyLight.shadow.camera.bottom = -78;
keyLight.shadow.camera.near = 10; keyLight.shadow.camera.far = 260;
keyLight.shadow.bias = -0.0008; keyLight.shadow.normalBias = 0.35;
scene.add(keyLight, keyLight.target);
const flashLight = new THREE.DirectionalLight(0xdfe8ff, 0);
flashLight.position.set(40, 120, 30); scene.add(flashLight, flashLight.target);
const arcLights = [];
