/* ---------- plateau: disc of radius 90 with gentle height variation and a cliff falling into fog ---------- */
const wetMats = [];                                     /* materials whose roughness follows the global wetness */
function wetMaterial(m, dry, env) { m.userData.dryRough = dry === undefined ? 0.9 : dry; m.userData.env = env === undefined ? 1 : env; m.userData.baseColor = m.color.clone(); wetMats.push(m); return m; }
(function () {
  const rings = 64, segs = 128, pos = [], uv = [], idx = [];
