  /* cliff wall */
  const cp = [], ci = [], rows = 10, pr = mulberry32(SEED + 23);
  for (let i = 0; i <= rows; i++) {
    const f = i / rows, y0 = -f * 75;
    for (let j = 0; j <= segs; j++) {
      const a = j / segs * TAU, jj = j % segs;
      const bulge = (i === 0 ? 0 : (hash01(jj, i, 5) - 0.5) * 3.0 + Math.sin(a * 9 + i) * 1.2) - f * 5;
      const r = PLATEAU_R + bulge, x = Math.cos(a) * r, z = Math.sin(a) * r;
      cp.push(x, (i === 0 ? terrainH(Math.cos(a) * PLATEAU_R, Math.sin(a) * PLATEAU_R) : y0 + (hash01(jj, i, 9) - 0.5) * 2), z);
    }
  }
  for (let i = 0; i < rows; i++) for (let j = 0; j < segs; j++) { const a = i * (segs + 1) + j, b = a + segs + 1; ci.push(a, b, a + 1, b, b + 1, a + 1); }
  const cg = new THREE.BufferGeometry(); cg.setAttribute('position', new THREE.Float32BufferAttribute(cp, 3)); cg.setIndex(ci); cg.computeVertexNormals();
  const cm = wetMaterial(new THREE.MeshStandardMaterial({ color: 0x2b2e33, roughness: 0.9, metalness: 0, flatShading: true }), 0.9, 0.6);
