/* ---------- grass: 100,000 instanced blades; all bending is closed-form in the vertex shader ---------- */
const NEV = 24;                                         /* footfall / shockwave rings visible to the shader at once */
const GRASS_EVENTS = [];                                /* {x, z, t, s (strength), r (reach in metres)} — filled from the event table */
const grassU = {
  uMt: SU.uMt, uFogColor: SU.uFogColor, uFogDensity: SU.uFogDensity, uFlash: SU.uFlash, uWet: SU.uWet, uCam: SU.uCam,
  uKeyDir: SU.uKeyDir, uKeyCol: SU.uKeyCol, uAmb: SU.uAmb, uALp: SU.uALp, uALi: SU.uALi, uFlashDir: SU.uFlashDir,
  uEvA: { value: [] }, uEvB: { value: new Float32Array(NEV) }, uBlob: { value: new THREE.Vector4(40, 0, 15, 0.45) }
