for (let i = 0; i < NEV; i++) grassU.uEvA.value.push(new THREE.Vector4(0, 0, -100, 0));
(function () {
  const N = COUNTS.grassBlades, r = mulberry32(SEED + 101);
  const g = new THREE.InstancedBufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([-0.5, 0, 0, 0.5, 0, 0, -0.5, 0.34, 0, 0.5, 0.34, 0, -0.5, 0.68, 0, 0.5, 0.68, 0, 0, 1, 0], 3));
