    off[i * 3] = x; off[i * 3 + 1] = terrainH(x, z); off[i * 3 + 2] = z;
    par[i * 4] = 0.4 + 0.5 * r();                       /* height 0.4 .. 0.9 m */
    par[i * 4 + 1] = 0.085 + 0.06 * r();                /* base width */
