    uniform vec3 uCam, uKeyDir, uKeyCol, uAmb, uFlashDir; uniform float uWet; uniform vec3 uALp[6]; uniform float uALi[6]; uniform vec4 uBlob;
    varying vec3 vN; varying vec3 vW; varying float vH; varying vec3 vRnd; varying float vDepth; varying float vFlat;` + GLSL_FOG_PARS + `
