    transparent: true, depthWrite: false, uniforms: { uMt: SU.uMt, uCam: SU.uCam, uVel: { value: RAIN_VEL }, uFogColor: SU.uFogColor, uFogDensity: SU.uFogDensity, uFlash: SU.uFlash, uPx: SU.uPx },
