/* =====================================================================
   TITAN GRAPHICS — instanced boulders, collapse ballistics, weak points,
   binding lightning arcs (20 Hz seeded), sky bolts.
   ===================================================================== */
const BOULDER_COUNT_PER_BONE = [12, 8, 12, 9, 8, 8, 6, 8, 8, 6, 9, 8, 6, 9, 8, 6];
const BOULDER_SIZE = [[0.95, 1.8], [0.9, 1.5], [1.0, 2.0], [0.8, 1.5], [0.75, 1.25], [0.7, 1.15], [0.8, 1.2], [0.75, 1.25], [0.7, 1.15], [0.8, 1.2], [0.85, 1.45], [0.7, 1.2], [0.6, 0.95], [0.85, 1.45], [0.7, 1.2], [0.6, 0.95]];
const BOULDERS = [];
const REF_T = 16.4;                                     /* neutral standing pose used to keep boulders from touching */
(function generateBoulders() {
  const P = titanPose(REF_T), placed = [];
  const wps = [wpPos(P, 0), wpPos(P, 1), wpPos(P, 2)], pins = [pinPos(P, 0), pinPos(P, 2)];
  function tryPlace(b, loc, rad, opts) {
    const w = boneLocal(P, b, loc);
    for (let k = 0; k < placed.length; k++) if (vdist(w, placed[k].w) < 1.1 * (rad + placed[k].rad) + 0.22) return false;
    if (!opts) {
      for (let k = 0; k < 3; k++) if (vdist(w, wps[k]) < rad * 1.1 + 1.15) return false;
      for (let k = 0; k < 2; k++) if (vdist(w, pins[k]) < rad * 1.1 + 0.35) return false;
      if (b === B.CHEST && loc[0] > 0.6 && Math.abs(loc[1] - 3.4) < rad + 1.9 && Math.abs(loc[2]) < rad + 2.1) return false;   /* keep the core's window for the cover stones */
    }
    const sc = opts && opts.sc ? opts.sc : [rad * rr(0.78, 1.12), rad * rr(0.72, 1.08), rad * rr(0.78, 1.12)];
    const ax = vnorm([rr(-1, 1), rr(-1, 1), rr(-1, 1)]);
