#!/usr/bin/env python3
"""Check that the WebGL output at a given simTime is identical regardless of history (readPixels hash inside the page)."""
import sys, os, json
from playwright.sync_api import sync_playwright
html = sys.argv[1]
JS = """() => {
  const gl = renderer.getContext(); const w = gl.drawingBufferWidth, h = gl.drawingBufferHeight; const buf = new Uint8Array(w * h * 4);
  function hashAt(t) { renderAt(t); gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf); let a = 2166136261 >>> 0; for (let i = 0; i < buf.length; i += 1) { a ^= buf[i]; a = Math.imul(a, 16777619) >>> 0; } return a; }
  function diff(t, other) { renderAt(t); gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf); const ref = buf.slice(); for (const o of other) renderAt(o); renderAt(t); gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf);
    let n = 0, mx = 0; for (let i = 0; i < buf.length; i++) { const d = Math.abs(buf[i] - ref[i]); if (d) { n++; if (d > mx) mx = d; } } return [n, mx]; }
  const out = {};
  for (const t of [0, 3.6, 4.4, 7.55, 11.3, 12.03, 19.4, 20.2, 25.05, 27.0, 29.6, 31.0, 36.0, 40]) {
    const a = hashAt(t), b = hashAt(t); const d = diff(t, [38.2, 0.7, 26.1, 13.3, 5.05]);
    out[t] = { repeatSame: a === b, afterScrubDiffPixels: d[0], maxDelta: d[1] };
  }
  return out; }"""
with sync_playwright() as p:
    b = p.chromium.launch(headless=True, args=["--use-angle=metal", "--enable-webgl", "--ignore-gpu-blocklist", "--enable-gpu"])
    pg = b.new_page(viewport={"width": 960, "height": 540}, device_scale_factor=1)
    pg.goto("file://" + os.path.abspath(html))
    pg.wait_for_function("() => typeof window.renderAt === 'function' && state !== 'INIT'", timeout=60000)
    pg.click('#btn-toggle')
    res = pg.evaluate(JS)
    for k, v in res.items(): print(k, json.dumps(v))
    b.close()

