#!/usr/bin/env python3
"""Framing audit: for every 0.05 s of the timeline, project the hunter and the Titan's chest/head and report when they leave the frame."""
import sys, os, json
from playwright.sync_api import sync_playwright
html = sys.argv[1]
JS = """() => {
  const res = { shots: {} }; const W = innerWidth, H = innerHeight;
  function ndc(p) { const v = new THREE.Vector3(p[0], p[1], p[2]); const c = v.clone().applyMatrix4(camera.matrixWorldInverse); v.project(camera); return [v.x, v.y, c.z < 0]; }
  const bad = { hunter: [], chest: [], head: [], hunterLow: [] }; const dockTop = -1 + 2 * 70 / H;
  let worst = { hunterY: 9, hunterT: 0 };
  for (let t = 0; t <= 40.0001; t += 0.05) {
    const P = updateCamera(t), mt = motionTime(t), s = shotAt(t);
    const h = ndc(hunterChest(mt)), c = ndc(chestCenter(P)), hd = ndc(P.tip[B.HEAD]);
    const inF = (q, m) => q[2] && Math.abs(q[0]) <= m && Math.abs(q[1]) <= m;
    if (!inF(h, 1.0)) bad.hunter.push(+t.toFixed(2));
    else if (h[1] < dockTop + 0.02 && Math.abs(h[0]) < 0.3) bad.hunterLow.push(+t.toFixed(2));
    if (t < 29.5 && !inF(c, 1.0)) bad.chest.push(+t.toFixed(2));
    if (t < 29.5 && !inF(hd, 1.0)) bad.head.push(+t.toFixed(2));
    if (h[1] < worst.hunterY) { worst.hunterY = +h[1].toFixed(3); worst.hunterT = +t.toFixed(2); }
    const k = 'shot' + s; const r = res.shots[k] || (res.shots[k] = { hx: [9, -9], hy: [9, -9], cy: [9, -9], fov: [999, 0] });
    r.hx[0] = Math.min(r.hx[0], h[0]); r.hx[1] = Math.max(r.hx[1], h[0]); r.hy[0] = Math.min(r.hy[0], h[1]); r.hy[1] = Math.max(r.hy[1], h[1]);
    if (t < 29.5) { r.cy[0] = Math.min(r.cy[0], c[1]); r.cy[1] = Math.max(r.cy[1], c[1]); }
    r.fov[0] = Math.min(r.fov[0], camera.fov); r.fov[1] = Math.max(r.fov[1], camera.fov);
  }
  function ranges(a) { const out = []; let s = null, p = null; for (const t of a) { if (s === null) { s = t; } else if (t - p > 0.051) { out.push(s + '-' + p); s = t; } p = t; } if (s !== null) out.push(s + '-' + p); return out.join(' '); }
  for (const k in res.shots) for (const q of ['hx', 'hy', 'cy', 'fov']) res.shots[k][q] = res.shots[k][q].map(v => +v.toFixed(2));
  return { size: [W, H], dockTopNdc: +dockTop.toFixed(3), hunterOut: ranges(bad.hunter), hunterBehindDock: ranges(bad.hunterLow), chestOut: ranges(bad.chest), headOut: ranges(bad.head), worst: worst, shots: res.shots };
}"""
with sync_playwright() as p:
    b = p.chromium.launch(headless=True, args=["--use-angle=metal", "--enable-webgl", "--ignore-gpu-blocklist", "--enable-gpu"])
    for size in [(1920, 1080), (1280, 1340)]:
        pg = b.new_page(viewport={"width": size[0], "height": size[1]}, device_scale_factor=1)
        pg.goto("file://" + os.path.abspath(html))
        pg.wait_for_function("() => typeof window.renderAt === 'function' && state !== 'INIT'", timeout=60000)
        pg.click('#btn-toggle')
        r = pg.evaluate(JS)
        print(json.dumps({k: v for k, v in r.items() if k != 'shots'}))
        for k, v in r['shots'].items(): print('   ', k, json.dumps(v))
        pg.close()
    b.close()

